INSERT INTO `comments` VALUES (1,1,NULL,16,'Administrator','admin@syntaxcore.com','Selamat datang semuanya! Modul CMS publik telah aktif dan siap digunakan. Silakan uji coba fitur komentar ini.','approved','127.0.0.1','Mozilla/5.0 (SyntaxCore Seeder)','2026-09-11 15:49:50','2026-09-11 15:49:50'),(2,1,1,NULL,'Pengunjung Tamu','guest@example.com','Keren sekali! Tampilan bersih dan sangat responsif.','approved','127.0.0.1','Mozilla/5.0 (SyntaxCore Seeder)','2026-09-11 16:49:50','2026-09-11 16:49:50'),(3,3,NULL,NULL,'Reviewer','reviewer@example.com','First comment on test article','approved',NULL,NULL,'2026-09-11 17:50:10','2026-09-11 17:50:10'),(4,3,3,NULL,'Author Reply','author@example.com','Thanks for reading!','approved',NULL,NULL,'2026-09-11 17:50:10','2026-09-11 17:50:10'),(41,2,NULL,3,'Custom Superadmin','admin@gmail.com','tes','rejected','172.19.0.1','Public Browser','2026-09-11 18:03:14','2026-09-11 18:03:58'),(92,44,NULL,16,'Muh Fajar Mujahid, S.Pd','pkbmsupriadi1@gmail.com','Alhamdulillah kegiatan SuperCamp di Wana Wisata Winong terlaksana dengan sukses dan penuh antusiasme dari seluruh warga belajar. Tetap semangat belajar!','approved','127.0.0.1','Mozilla/5.0 (SyntaxCore Seeder)','2026-09-11 23:52:15','2026-09-11 23:52:15'),(93,44,92,NULL,'Ismail','ismail.alumni@example.com','Seru sekali acaranya! Semoga adik-adik kelas semakin kompak dan berprestasi.','approved','127.0.0.1','Mozilla/5.0 (SyntaxCore Seeder)','2026-09-12 00:52:15','2026-09-12 00:52:15');
