INSERT INTO `pages` VALUES (1,'Beranda Utama','beranda','<h2>Selamat Datang di PKBM S. Supriadi</h2><p>PKBM S. Supriadi merupakan lembaga pendidikan nonformal resmi di bawah naungan Dinas Pendidikan Kota Malang dengan NPSN P9962749 dan telah terakreditasi. Kami hadir memberikan kesempatan belajar yang fleksibel dan berkualitas bagi siapa saja yang ingin melanjutkan pendidikan kesetaraan Paket A (setara SD), Paket B (setara SMP), dan Paket C (setara SMA).</p>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Website Resmi PKBM S.Supriadi - Sekolah Kesetaraan Kota Malang','Website Resmi PKBM S.Supriadi Kota Malang menyelenggarakan pendidikan kesetaraan Paket A, B, C dengan sistem belajar fleksibel dan keterampilan vokasi.','published',1,'2026-09-11 17:49:50','2026-09-11 17:49:50'),(2,'Tentang Kami','tentang-kami','<h2>Tentang PKBM S.Supriadi Kota Malang</h2><p>PKBM S.Supriadi adalah Pusat Kegiatan Belajar Masyarakat berizin resmi dari Dinas Pendidikan Kota Malang. Kami berkomitmen membuka akses pendidikan seluas-luasnya melalui kesetaraan Paket A, Paket B, dan Paket C dengan program vokasi praktis.</p>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Tentang Kami - PKBM S.Supriadi','Mengenal visi dan filosofi pendidikan inklusif PKBM S.Supriadi.','published',19,'2026-09-11 17:49:50','2026-09-11 17:49:50'),(3,'Berita & Pengumuman','berita','<p class=\"lead text-muted\">Dapatkan rilis berita, agenda akademik, dan liputan kegiatan terbaru dari PKBM S.Supriadi.</p>','news_index','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Warta & Berita Terkini - PKBM S.Supriadi','Arsip berita, pengumuman, dan artikel edukasi terkini PKBM S.Supriadi Malang.','published',20,'2026-09-11 17:49:50','2026-09-11 17:49:50'),(4,'Baca Berita','baca-berita',NULL,'news_single','default','{\"style\": \"cards\", \"enabled\": true, \"per_page\": 15, \"moderation\": false, \"allow_guests\": true}','Detail Berita - PKBM S.Supriadi','Halaman pembaca detail berita dengan interaksi komentar terintegrasi.','published',21,'2026-09-11 17:49:50','2026-09-11 17:49:50'),(10,'Halaman Uji 1789149138','halaman-uji-1789149138','<p>Konten pengujian otomatis</p>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 20, \"moderation\": false, \"allow_guests\": true}',NULL,NULL,'published',0,'2026-09-11 17:52:18','2026-09-11 17:52:18'),(11,'Halaman Uji 1789149147','halaman-uji-1789149147','<p>Konten pengujian otomatis</p>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 20, \"moderation\": false, \"allow_guests\": true}',NULL,NULL,'published',0,'2026-09-11 17:52:27','2026-09-11 17:52:27'),(54,'Profil Sekolah','profil-sekolah','<div class=\"mb-4 text-center\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/03/foto_700kb_9-1100x600.jpg\" alt=\"Profil PKBM S.Supriadi\" class=\"img-fluid rounded-3 shadow-sm mb-3\"></div><h2>Profil PKBM S.Supriadi</h2><p><strong>PKBM S.Supriadi</strong> merupakan lembaga pendidikan nonformal yang berkomitmen memberikan kesempatan belajar bagi masyarakat luas. PKBM ini hadir sebagai solusi pendidikan bagi siapa saja yang ingin melanjutkan pendidikan namun memiliki keterbatasan waktu, usia, maupun kesempatan untuk mengikuti pendidikan formal.</p><p>PKBM S.Supriadi menyelenggarakan program pendidikan kesetaraan yang meliputi <strong>Paket A (setara SD), Paket B (setara SMP), dan Paket C (setara SMA)</strong>. Dengan sistem pembelajaran yang fleksibel dan menyesuaikan kebutuhan peserta didik, proses belajar dapat dilakukan secara efektif sehingga memudahkan masyarakat untuk tetap melanjutkan pendidikan.</p><p>Selain pembelajaran akademik, PKBM S.Supriadi juga memberikan berbagai kegiatan pengembangan keterampilan seperti <strong>kelas komputer, cooking class, serta kegiatan pembelajaran lainnya</strong> yang bertujuan untuk meningkatkan kemampuan dan kemandirian peserta didik. Hal ini diharapkan dapat menjadi bekal yang bermanfaat bagi kehidupan serta masa depan mereka.</p><p>Dengan dukungan tenaga pendidik yang berkompeten serta fasilitas pembelajaran yang memadai, PKBM S.Supriadi terus berupaya menjadi lembaga pendidikan yang <strong>bermanfaat bagi masyarakat, membentuk karakter yang baik, serta membantu peserta didik meraih masa depan yang lebih baik</strong>.</p>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Profil Sekolah - PKBM S.Supriadi','Mengenal profil PKBM S.Supriadi, lembaga pendidikan nonformal di Kota Malang.','published',2,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(55,'Identitas Sekolah','identitas-sekolah','<div class=\"mb-4 text-center\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/03/foto_700kb_8-e1772973100488-1100x600.jpg\" alt=\"Identitas PKBM S.Supriadi\" class=\"img-fluid rounded-3 shadow-sm mb-3\"></div><h2>Identitas Resmi Sekolah</h2><table class=\"table table-bordered table-striped mt-3\"><tbody><tr><th width=\"35%\">Nama Sekolah</th><td><strong>PKBM S.SUPRIADI</strong></td></tr><tr><th>NPSN</th><td><span class=\"badge bg-success\">P9962749</span></td></tr><tr><th>Status Lembaga</th><td>Swasta</td></tr><tr><th>Bentuk Pendidikan</th><td>Pendidikan Nonformal (PKBM)</td></tr><tr><th>Status Kepemilikan</th><td>Yayasan</td></tr><tr><th>SK Pendirian Sekolah</th><td>AHU-0006544.AH.01.04.Tahun 2016</td></tr><tr><th>Tanggal SK Pendirian</th><td>2016-02-28</td></tr><tr><th>SK Izin Operasional</th><td>420.3/0019/35.73.406/2022</td></tr><tr><th>Tanggal SK Operasional</th><td>2022-03-31</td></tr></tbody></table><h4 class=\"mt-4 mb-2\">Alamat & Lokasi Sekolah</h4><table class=\"table table-bordered table-striped\"><tbody><tr><th width=\"35%\">Alamat</th><td>Jl. S.Supriadi IX No.42 RT.13 RW.04</td></tr><tr><th>Desa / Kelurahan</th><td>Sukun</td></tr><tr><th>Kecamatan</th><td>Sukun</td></tr><tr><th>Kabupaten / Kota</th><td>Kota Malang</td></tr><tr><th>Provinsi</th><td>Jawa Timur</td></tr><tr><th>Kode Pos</th><td>65147</td></tr><tr><th>Telepon / WhatsApp</th><td>085954447600</td></tr><tr><th>Email Resmi</th><td>pkbmsupriadi1@gmail.com</td></tr></tbody></table>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Identitas Sekolah - PKBM S.Supriadi','Data legalitas resmi, NPSN P9962749, SK Pendirian, dan alamat PKBM S.Supriadi Malang.','published',3,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(56,'Visi & Misi','visi-misi','<div class=\"mb-4 text-center\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/03/foto_700kb_7-1100x600.jpg\" alt=\"Visi dan Misi PKBM S.Supriadi\" class=\"img-fluid rounded-3 shadow-sm mb-3\"></div><div class=\"p-4 bg-light rounded-3 border mb-4\"><h3 class=\"text-success fw-bold mb-2\"><i class=\"fa-solid fa-bullseye me-2\"></i>Visi Sekolah</h3><p class=\"lead mb-0\" style=\"font-size: 17px; line-height: 1.7;\">\"Menjadi lembaga pendidikan masyarakat yang berkualitas, bermanfaat bagi lingkungan sekitar, serta mampu membentuk peserta didik yang berakhlak baik, berpengetahuan, dan memiliki keterampilan yang berguna untuk kehidupan serta masa depan yang lebih baik.\"</p></div><h3 class=\"text-success fw-bold mb-3\"><i class=\"fa-solid fa-list-check me-2\"></i>Misi Sekolah</h3><ol class=\"list-group list-group-numbered shadow-sm mb-4\"><li class=\"list-group-item p-3\">Menyelenggarakan pendidikan yang terbuka dan bermanfaat bagi seluruh lapisan masyarakat sebagai sarana meningkatkan kualitas sumber daya manusia.</li><li class=\"list-group-item p-3\">Menanamkan nilai-nilai keagamaan, akhlak mulia, dan sikap positif dalam setiap proses pembelajaran sehingga peserta didik memiliki karakter yang baik.</li><li class=\"list-group-item p-3\">Mengembangkan pengetahuan, keterampilan, serta kemampuan peserta didik agar mampu mandiri, produktif, dan siap menghadapi tantangan di masa depan.</li><li class=\"list-group-item p-3\">Menciptakan lingkungan belajar yang nyaman, inklusif, dan mendukung perkembangan potensi setiap peserta didik.</li><li class=\"list-group-item p-3\">Mendorong peserta didik untuk memiliki semangat belajar sepanjang hayat demi meraih masa depan yang lebih baik.</li></ol>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Visi & Misi - PKBM S.Supriadi','Visi dan 5 Misi utama PKBM S.Supriadi dalam mewujudkan pendidikan kesetaraan berkualitas di Kota Malang.','published',4,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(57,'Sambutan Kepala Sekolah','sambutan-kepala-sekolah','<div class=\"row align-items-center g-4 mb-4\"><div class=\"col-md-4 text-center\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/03/foto_batik_700kb-e1772858295746.jpg\" alt=\"Muh Fajar Mujahid, S.Pd\" class=\"img-fluid rounded-3 shadow-sm border\" style=\"max-height: 280px; object-fit: cover;\"></div><div class=\"col-md-8\"><span class=\"badge bg-success mb-2\">Kepala PKBM S. Supriadi</span><h3 class=\"fw-bold mb-1\">Muh Fajar Mujahid, S.Pd</h3><p class=\"text-muted small\">Pusat Kegiatan Belajar Masyarakat (PKBM) S. Supriadi Kota Malang</p></div></div><p><em>Assalamu’alaikum warahmatullahi wabarakatuh,</em></p><p>Puji syukur kita panjatkan ke hadirat Allah SWT atas segala rahmat dan karunia-Nya sehingga website PKBM ini dapat hadir sebagai sarana informasi dan komunikasi bagi masyarakat. Melalui website ini kami berharap masyarakat dapat lebih mengenal berbagai program, kegiatan, serta layanan pendidikan yang diselenggarakan di PKBM. Kehadiran website ini juga menjadi bentuk komitmen kami dalam memberikan informasi yang terbuka, transparan, dan mudah diakses oleh seluruh masyarakat.</p><p>PKBM merupakan lembaga pendidikan nonformal yang memberikan kesempatan belajar bagi masyarakat yang ingin melanjutkan pendidikan. Program pendidikan yang kami selenggarakan meliputi Paket A, Paket B, dan Paket C, yang dirancang untuk membantu masyarakat memperoleh pendidikan yang setara dengan pendidikan formal. PKBM juga <strong>terbuka bagi siapa pun dan dari berbagai kalangan tanpa batasan usia</strong>, sehingga setiap orang memiliki kesempatan yang sama untuk belajar, meningkatkan pengetahuan, serta mengembangkan potensi diri.</p><p>Akhir kata, kami mengucapkan terima kasih kepada semua pihak yang telah mendukung keberadaan dan perkembangan PKBM. Kami berharap melalui website ini dapat terjalin komunikasi yang baik antara lembaga, peserta didik, orang tua, serta masyarakat luas. Semoga PKBM dapat terus menjadi tempat belajar yang bermanfaat, menciptakan generasi yang berilmu, mandiri, dan siap menghadapi tantangan masa depan.</p><p><em>Wassalamu’alaikum warahmatullahi wabarakatuh.</em></p>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Sambutan Kepala Sekolah - PKBM S.Supriadi','Sambutan resmi Kepala Sekolah PKBM S.Supriadi, Bapak Muh Fajar Mujahid, S.Pd.','published',5,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(58,'Sejarah Singkat','sejarah-singkat','<h2>Sejarah Singkat PKBM S.Supriadi</h2><p>PKBM S.Supriadi berawal dari kepedulian para pendidik dan tokoh masyarakat di kawasan Sukun Kota Malang terhadap warga yang mengalami putus sekolah atau terkendala mengikuti jalur pendidikan formal karena faktor ekonomi, usia, dan jam kerja.</p><p>Berdiri secara resmi sejak tahun 2016 melalui SK AHU-0006544.AH.01.04.Tahun 2016 dan diperkuat dengan Izin Operasional Dinas Pendidikan Kota Malang No. 420.3/0019/35.73.406/2022, lembaga ini terus berinovasi memadukan kurikulum pendidikan kesetaraan nasional dengan pelatihan kecakapan hidup (life skills), teknologi informasi, dan kewirausahaan.</p>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Sejarah Singkat - PKBM S.Supriadi','Sejarah berdirinya PKBM S.Supriadi dalam memajukan pendidikan kesetaraan di Malang.','published',6,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(59,'Struktur Organisasi','struktur-organisasi','<h2>Struktur Organisasi PKBM S.Supriadi</h2><p class=\"text-muted\">Susunan kepengurusan dan manajemen operasional lembaga:</p><div class=\"row g-3 my-3\"><div class=\"col-md-6\"><div class=\"card p-3 border shadow-sm\"><h5>Ketua Yayasan / Penyelenggara</h5><p class=\"text-muted small mb-0\">Dewan Pembina Yayasan PKBM S. Supriadi</p></div></div><div class=\"col-md-6\"><div class=\"card p-3 border shadow-sm border-success\"><h5>Kepala PKBM</h5><p class=\"text-success fw-semibold small mb-0\">Muh Fajar Mujahid, S.Pd</p></div></div><div class=\"col-md-6\"><div class=\"card p-3 border shadow-sm\"><h5>Operator Sekolah & IT Support</h5><p class=\"text-muted small mb-0\">Dimas Arya Agung Nugraha, S.Pd</p></div></div><div class=\"col-md-6\"><div class=\"card p-3 border shadow-sm\"><h5>Koordinator Tutor & Kurikulum</h5><p class=\"text-muted small mb-0\">Retno Wahyu Kusuma, S.Pd</p></div></div></div>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Struktur Organisasi - PKBM S.Supriadi','Struktur organisasi dan jajaran pengurus PKBM S.Supriadi.','published',7,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(60,'Staf Pengajar','staf-pengajar','<h2>Daftar Staf Pengajar (Guru / Tutor)</h2><p class=\"text-muted mb-4\">Tenaga pendidik berkompeten dan berdedikasi tinggi di PKBM S.Supriadi:</p><div class=\"row g-4\"><div class=\"col-md-4 col-sm-6\"><div class=\"card h-100 border text-center p-3 shadow-sm\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/03/foto_formal_hijab_700kb-386x500.jpg\" class=\"rounded-3 img-fluid mb-3 mx-auto\" style=\"height: 180px; object-fit: cover;\"><h5 class=\"fw-bold mb-1\">Adinda Sukma Nur Chaya, S.Pd</h5><p class=\"text-muted small mb-0\">Bahasa Jawa, Pendidikan Kewarganegaraan</p></div></div><div class=\"col-md-4 col-sm-6\"><div class=\"card h-100 border text-center p-3 shadow-sm\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/08/WhatsApp-Image-2026-08-26-at-12.46.21-386x500.jpeg\" class=\"rounded-3 img-fluid mb-3 mx-auto\" style=\"height: 180px; object-fit: cover;\"><h5 class=\"fw-bold mb-1\">ALFINDHA ROSA SANITA, S.Pd</h5><p class=\"text-muted small mb-0\">Ilmu Pengetahuan Alam, Matematika</p></div></div><div class=\"col-md-4 col-sm-6\"><div class=\"card h-100 border text-center p-3 shadow-sm\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/03/foto_flanel_700kb-386x500.jpg\" class=\"rounded-3 img-fluid mb-3 mx-auto\" style=\"height: 180px; object-fit: cover;\"><h5 class=\"fw-bold mb-1\">Dimas Arya Agung Nugraha, S.Pd</h5><p class=\"text-muted small mb-0\">Teknologi Informasi & Komunikasi (TIK)</p></div></div><div class=\"col-md-4 col-sm-6\"><div class=\"card h-100 border text-center p-3 shadow-sm\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/03/foto_batik_1200x245-1-386x500.jpg\" class=\"rounded-3 img-fluid mb-3 mx-auto\" style=\"height: 180px; object-fit: cover;\"><h5 class=\"fw-bold mb-1\">Ilham Gus Adhiim, M.Pd</h5><p class=\"text-muted small mb-0\">Bahasa Inggris</p></div></div><div class=\"col-md-4 col-sm-6\"><div class=\"card h-100 border text-center p-3 shadow-sm\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/03/pasfoto_700kb-386x500.jpg\" class=\"rounded-3 img-fluid mb-3 mx-auto\" style=\"height: 180px; object-fit: cover;\"><h5 class=\"fw-bold mb-1\">Retno Wahyu Kusuma, S.Pd</h5><p class=\"text-muted small mb-0\">Bahasa Indonesia, Cooking Class, IPS</p></div></div><div class=\"col-md-4 col-sm-6\"><div class=\"card h-100 border text-center p-3 shadow-sm\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/03/foto_work_jacket_700kb-386x500.jpg\" class=\"rounded-3 img-fluid mb-3 mx-auto\" style=\"height: 180px; object-fit: cover;\"><h5 class=\"fw-bold mb-1\">Zulius Nilam Cahya, S.Pd</h5><p class=\"text-muted small mb-0\">Bahasa Indonesia</p></div></div></div>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Staf Pengajar - PKBM S.Supriadi','Daftar guru pengajar dan tutor berpengalaman di PKBM S.Supriadi Malang.','published',8,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(61,'Staf Tenaga Kependidikan','staf-tenaga-kependidikan','<h2>Staf Tenaga Kependidikan</h2><p class=\"text-muted mb-4\">Mendukung kelancaran layanan administrasi, pendataan Dapodik, dan operasional warga belajar:</p><div class=\"row g-4\"><div class=\"col-md-4 col-sm-6\"><div class=\"card h-100 border text-center p-3 shadow-sm\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/03/foto_flanel_700kb-386x500.jpg\" class=\"rounded-3 img-fluid mb-3 mx-auto\" style=\"height: 180px; object-fit: cover;\"><h5 class=\"fw-bold mb-1\">Dimas Arya Agung Nugraha, S.Pd</h5><p class=\"text-muted small mb-0\">Operator Sekolah & Dapodik</p></div></div><div class=\"col-md-4 col-sm-6\"><div class=\"card h-100 border text-center p-3 shadow-sm\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/03/foto_batik_700kb-e1772858295746-386x500.jpg\" class=\"rounded-3 img-fluid mb-3 mx-auto\" style=\"height: 180px; object-fit: cover;\"><h5 class=\"fw-bold mb-1\">Muh Fajar Mujahid, S.Pd</h5><p class=\"text-muted small mb-0\">Kepala Sekolah</p></div></div></div>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Staf Tenaga Kependidikan - PKBM S.Supriadi','Profil staf administrasi dan operator sekolah PKBM S.Supriadi.','published',9,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(62,'Fasilitas Sekolah','fasilitas-sekolah','<h2>Fasilitas Pendukung Pembelajaran</h2><p>Guna menunjang efektivitas kegiatan belajar mengajar, PKBM S.Supriadi menyediakan berbagai sarana dan prasarana memadai:</p><div class=\"row g-4 mt-2\"><div class=\"col-md-6\"><div class=\"card border-0 shadow-sm overflow-hidden\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/03/foto_700kb_6-1070x900.jpg\" class=\"card-img-top\" style=\"height: 220px; object-fit: cover;\"><div class=\"card-body\"><h5>Laboratorium Komputer</h5><p class=\"text-muted small mb-0\">Dilengkapi dengan perangkat komputer modern dan koneksi internet stabil untuk pembelajaran TIK, ujian berbasis daring, dan pelatihan digital marketing.</p></div></div></div><div class=\"col-md-6\"><div class=\"card border-0 shadow-sm overflow-hidden\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/03/foto_700kb_16-1200x845.jpg\" class=\"card-img-top\" style=\"height: 220px; object-fit: cover;\"><div class=\"card-body\"><h5>Ruang Kelas Nyaman & Fleksibel</h5><p class=\"text-muted small mb-0\">Ruang belajar yang bersih, kondusif, dan mendukung pembelajaran interaktif tatap muka maupun diskusi kelompok.</p></div></div></div></div>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Fasilitas Sekolah - PKBM S.Supriadi','Fasilitas laboratorium komputer dan sarana belajar PKBM S.Supriadi.','published',10,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(63,'Galeri Sekolah','galeri-sekolah','<h2>Galeri Dokumentasi Kegiatan</h2><p class=\"text-muted mb-4\">Kilas balik aktivitas, suasana belajar di alam terbuka, dan momen kebersamaan warga belajar PKBM S.Supriadi:</p><div class=\"row g-3\"><div class=\"col-md-4\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/05/WhatsApp-Image-2026-05-06-at-20.55.03-680x554.jpeg\" class=\"img-fluid rounded-3 shadow-sm w-100\" style=\"height: 200px; object-fit: cover;\"></div><div class=\"col-md-4\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/05/WhatsApp-Image-2026-05-05-at-18.22.12-680x554.jpeg\" class=\"img-fluid rounded-3 shadow-sm w-100\" style=\"height: 200px; object-fit: cover;\"></div><div class=\"col-md-4\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/04/WhatsApp-Image-2026-04-14-at-22.04.02-680x554.jpeg\" class=\"img-fluid rounded-3 shadow-sm w-100\" style=\"height: 200px; object-fit: cover;\"></div><div class=\"col-md-4\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/04/WhatsApp-Image-2026-04-13-at-15.25.31-1-680x554.jpeg\" class=\"img-fluid rounded-3 shadow-sm w-100\" style=\"height: 200px; object-fit: cover;\"></div><div class=\"col-md-4\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/04/WhatsApp-Image-2026-04-05-at-13.52.13-680x554.jpeg\" class=\"img-fluid rounded-3 shadow-sm w-100\" style=\"height: 200px; object-fit: cover;\"></div><div class=\"col-md-4\"><img src=\"https://pkbmsupriadi.sch.id/wp-content/uploads/2026/03/WhatsApp-Image-2026-03-11-at-09.27.27-2-680x554.jpeg\" class=\"img-fluid rounded-3 shadow-sm w-100\" style=\"height: 200px; object-fit: cover;\"></div></div>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Galeri Kegiatan - PKBM S.Supriadi','Foto dan dokumentasi kegiatan belajar warga PKBM S.Supriadi.','published',11,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(64,'Intrakurikuler','ekstrakurikuler','<h2>Program Intrakurikuler & Keterampilan Vokasi</h2><p>Selain kurikulum akademik kesetaraan, PKBM S.Supriadi membekali warga belajar dengan berbagai program keterampilan aplikatif:</p><div class=\"row g-4 mt-2\"><div class=\"col-md-6\"><div class=\"card border shadow-sm p-3 h-100\"><div class=\"d-flex align-items-center gap-3 mb-2\"><i class=\"fa-solid fa-laptop-code text-success fs-3\"></i><h5 class=\"mb-0\">Computer Class</h5></div><p class=\"text-muted small mb-0\">Pembelajaran keterampilan komputer praktis meliputi administrasi perkantoran, desain grafis, dan pemanfaatan internet untuk produktivitas kerja.</p></div></div><div class=\"col-md-6\"><div class=\"card border shadow-sm p-3 h-100\"><div class=\"d-flex align-items-center gap-3 mb-2\"><i class=\"fa-solid fa-utensils text-success fs-3\"></i><h5 class=\"mb-0\">Cooking Class</h5></div><p class=\"text-muted small mb-0\">Pelatihan tata boga dan kreasi kuliner untuk menumbuhkan minat dan keterampilan kewirausahaan di bidang kuliner.</p></div></div><div class=\"col-md-6\"><div class=\"card border shadow-sm p-3 h-100\"><div class=\"d-flex align-items-center gap-3 mb-2\"><i class=\"fa-solid fa-language text-success fs-3\"></i><h5 class=\"mb-0\">English Club</h5></div><p class=\"text-muted small mb-0\">Wadah latihan percakapan bahasa Inggris santai dan aplikatif untuk meningkatkan rasa percaya diri dan daya saing global.</p></div></div><div class=\"col-md-6\"><div class=\"card border shadow-sm p-3 h-100\"><div class=\"d-flex align-items-center gap-3 mb-2\"><i class=\"fa-solid fa-campground text-success fs-3\"></i><h5 class=\"mb-0\">SuperCamp & Outing Class</h5></div><p class=\"text-muted small mb-0\">Kegiatan edukasi di luar kelas dan perkemahan di alam terbuka untuk melatih kepemimpinan, kemandirian, dan kerja sama tim.</p></div></div></div>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Intrakurikuler - PKBM S.Supriadi','Program intrakurikuler dan kelas vokasi keterampilan di PKBM S.Supriadi.','published',12,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(65,'Kontak','kontak','<h2>Hubungi Kami</h2><p class=\"text-muted\">Untuk informasi pendaftaran, konsultasi program kesetaraan, atau kemitraan, silakan hubungi kontak resmi kami di bawah ini:</p><div class=\"row g-4 my-3\"><div class=\"col-md-6\"><div class=\"p-4 bg-light rounded-3 border h-100\"><h5 class=\"fw-bold mb-3\"><i class=\"fa-solid fa-location-dot text-success me-2\"></i>Alamat Sekolah</h5><p class=\"text-muted mb-2\">Jl. S.Supriadi IX No.42 RT.13 RW.04, Kel. Sukun, Kec. Sukun, Kota Malang, Jawa Timur 65147</p><hr><h5 class=\"fw-bold mb-3\"><i class=\"fa-solid fa-phone text-success me-2\"></i>Telepon & WhatsApp</h5><p class=\"text-muted mb-2\"><a href=\"https://wa.me/6285954447600\" target=\"_blank\" class=\"text-decoration-none fw-semibold text-dark\">085954447600 (Chat WA)</a></p><hr><h5 class=\"fw-bold mb-3\"><i class=\"fa-solid fa-envelope text-success me-2\"></i>Email Resmi</h5><p class=\"text-muted mb-0\"><a href=\"mailto:pkbmsupriadi1@gmail.com\" class=\"text-decoration-none text-dark\">pkbmsupriadi1@gmail.com</a></p></div></div><div class=\"col-md-6\"><div class=\"p-4 bg-light rounded-3 border h-100\"><h5 class=\"fw-bold mb-3\"><i class=\"fa-solid fa-share-nodes text-success me-2\"></i>Kanal Media Sosial</h5><ul class=\"list-unstyled d-flex flex-column gap-2 mb-0\"><li><a href=\"https://www.instagram.com/pkbmssupriadi/\" target=\"_blank\" class=\"text-decoration-none text-dark\"><i class=\"fa-brands fa-instagram text-danger me-2\"></i>Instagram: @pkbmssupriadi</a></li><li><a href=\"https://www.youtube.com/@PKBMSUPRIADI\" target=\"_blank\" class=\"text-decoration-none text-dark\"><i class=\"fa-brands fa-youtube text-danger me-2\"></i>YouTube: @PKBMSUPRIADI</a></li><li><a href=\"https://www.tiktok.com/@pkbmssupriadi\" target=\"_blank\" class=\"text-decoration-none text-dark\"><i class=\"fa-brands fa-tiktok me-2\"></i>TikTok: @pkbmssupriadi</a></li></ul></div></div></div>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Kontak Kami - PKBM S.Supriadi','Kontak resmi, telepon WA 085954447600, email, dan alamat PKBM S.Supriadi Malang.','published',13,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(66,'Kelulusan','kelulusan','<h2>Informasi Kelulusan Ujian Kesetaraan</h2><p>Pengumuman kelulusan resmi bagi peserta didik Paket A, Paket B, dan Paket C PKBM S.Supriadi Kota Malang diumumkan secara daring melalui portal ini atau dapat diambil langsung di kantor operasional sekolah.</p><div class=\"alert alert-success mt-4\"><i class=\"fa-solid fa-circle-check me-2\"></i>Selamat kepada seluruh alumni yang telah menyelesaikan program pendidikan kesetaraan dengan sukses. Ijazah resmi setara formal diterbitkan oleh Kementerian Pendidikan dasar dan Menengah.</div>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Informasi Kelulusan - PKBM S.Supriadi','Pengumuman kelulusan Paket A, Paket B, dan Paket C PKBM S.Supriadi.','published',14,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(67,'PPDB 2026','ppdb','<h2>Penerimaan Peserta Didik Baru (PPDB 2026)</h2><p class=\"lead\">Pendaftaran Warga Belajar Baru PKBM S.Supriadi Tahun Ajaran 2026/2027 telah dibuka!</p><div class=\"row g-4 my-3\"><div class=\"col-md-4\"><div class=\"card h-100 border p-3 shadow-sm border-success\"><h4>Paket A (Setara SD)</h4><p class=\"text-muted small\">Terbuka untuk usia sekolah dasar yang terkendala formal atau masyarakat dewasa yang belum memiliki ijazah SD.</p></div></div><div class=\"col-md-4\"><div class=\"card h-100 border p-3 shadow-sm border-primary\"><h4>Paket B (Setara SMP)</h4><p class=\"text-muted small\">Program kesetaraan jenjang menengah pertama dengan waktu belajar yang dapat disesuaikan.</p></div></div><div class=\"col-md-4\"><div class=\"card h-100 border p-3 shadow-sm border-info\"><h4>Paket C (Setara SMA)</h4><p class=\"text-muted small\">Pilihan tepat bagi pekerja yang ingin memiliki ijazah SMA untuk kenaikan karir atau lanjut kuliah.</p></div></div></div><div class=\"p-4 bg-light rounded border text-center\"><h5 class=\"fw-bold mb-2\">Ingin Mendaftar atau Berkonsultasi?</h5><p class=\"text-muted small mb-3\">Hubungi staf administrasi kami via WhatsApp langsung untuk panduan formulir dan syarat berkas.</p><a href=\"https://wa.me/6285954447600?text=Halo%20Admin%20PKBM%20S.Supriadi,%20saya%20ingin%20mendaftar%20PPDB%202026\" target=\"_blank\" class=\"btn btn-success px-4 py-2 rounded-pill\"><i class=\"fa-brands fa-whatsapp me-2\"></i>Daftar via WhatsApp (085954447600)</a></div>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','PPDB 2026 - Pendaftaran Siswa Baru PKBM S.Supriadi','Penerimaan Peserta Didik Baru PPDB 2026 Paket A, B, C di PKBM S.Supriadi Sukun Malang.','published',15,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(68,'Daftar Siswa Paket A','paket-a','<h2>Daftar Siswa & Rombel Paket A (Setara SD)</h2><p class=\"text-muted\">Jenjang pendidikan kesetaraan tingkat dasar (Kelas 1 sampai Kelas 6) PKBM S.Supriadi.</p><ul class=\"list-group list-group-flush shadow-sm border rounded\"><li class=\"list-group-item\">Kelas 1 Paket A</li><li class=\"list-group-item\">Kelas 2 Paket A</li><li class=\"list-group-item\">Kelas 3 Paket A</li><li class=\"list-group-item\">Kelas 4 Paket A</li><li class=\"list-group-item\">Kelas 5 Paket A</li><li class=\"list-group-item\">Kelas 6 Paket A</li></ul>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Daftar Siswa Paket A - PKBM S.Supriadi','Informasi rombel dan siswa Paket A PKBM S.Supriadi.','published',16,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(69,'Daftar Siswa Paket B','paket-b','<h2>Daftar Siswa & Rombel Paket B (Setara SMP)</h2><p class=\"text-muted\">Jenjang pendidikan kesetaraan tingkat menengah pertama (Kelas 7, 8, 9) PKBM S.Supriadi.</p><ul class=\"list-group list-group-flush shadow-sm border rounded\"><li class=\"list-group-item\">Kelas 7 Paket B</li><li class=\"list-group-item\">Kelas 8 Paket B</li><li class=\"list-group-item\">Kelas 9 Paket B</li></ul>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Daftar Siswa Paket B - PKBM S.Supriadi','Informasi rombel dan siswa Paket B PKBM S.Supriadi.','published',17,'2026-09-12 01:52:15','2026-09-12 01:52:15'),(70,'Daftar Siswa Paket C','paket-c','<h2>Daftar Siswa & Rombel Paket C (Setara SMA)</h2><p class=\"text-muted\">Jenjang pendidikan kesetaraan tingkat menengah atas (Kelas 10, 11, 12) PKBM S.Supriadi.</p><ul class=\"list-group list-group-flush shadow-sm border rounded\"><li class=\"list-group-item\">Kelas 10 Paket C</li><li class=\"list-group-item\">Kelas 11 Paket C</li><li class=\"list-group-item\">Kelas 12 Paket C</li></ul>','standard','default','{\"style\": \"cards\", \"enabled\": false, \"per_page\": 10, \"moderation\": false, \"allow_guests\": true}','Daftar Siswa Paket C - PKBM S.Supriadi','Informasi rombel dan siswa Paket C PKBM S.Supriadi.','published',18,'2026-09-12 01:52:15','2026-09-12 01:52:15');
